const templateForzadoRaw = (input.templateForzado || '').trim();
const templateForzadoNorm = templateForzadoRaw === 'Auto' ? '' : templateForzadoRaw;
const tipoEscrituraRaw = (input.tipoEscritura || '').trim();
const tipoEscrituraNorm = tipoEscrituraRaw === 'Auto' ? '' : tipoEscrituraRaw;
const estiloRedaccionRaw = (input.estiloRedaccion || '').toString().trim();
const estiloRedaccionNorm = estiloRedaccionRaw === 'Auto' ? '' : estiloRedaccionRaw;
const modoCustomRaw = (input.modoCustom || '').toString().trim();
const escrituraCustomRaw = modoCustomRaw;

function plainText(value) {
  return value
    .toString()
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function inferLengthHintFromReference(value) {
  const words = plainText(value).split(' ').filter(Boolean).length;
  if (words < 350) return '400–700 palabras';
  if (words < 700) return '700–1100 palabras';
  if (words < 1200) return '1000–1600 palabras';
  return '1400–2200 palabras';
}

function inferTemplateGuideFromReference(value) {
  const txt = plainText(value);
  const lower = txt.toLowerCase();
  const questionCountLocal = (txt.match(/\?/g) || []).length;
  const numberedSteps = /(^|\n)\s*\d+[.)]\s+/.test(value) || /\b(paso|step)\s+\d+\b/i.test(lower);
  const bullets = (value.match(/(^|\n)\s*[-*•]\s+/g) || []).length;

  if (questionCountLocal >= 4) {
    return 'Plantilla custom derivada de referencia: abrir con contexto breve y desarrollar bloque FAQ real (pregunta-respuesta). Evitar índice y navegación. Mantener lenguaje directo y operativo.';
  }
  if (numberedSteps) {
    return 'Plantilla custom derivada de referencia: abrir con contexto y continuar con secuencia ordenada de pasos en una sola lista continua. Evitar índice, breadcrumbs y navegación.';
  }
  if (bullets >= 4) {
    return 'Plantilla custom derivada de referencia: apertura breve y desarrollo tipo listado razonado con secciones claras por punto. Evitar navegación o índice al inicio.';
  }

  return 'Plantilla custom derivada de referencia: apertura directa + desarrollo en secciones con subtítulos claros + cierre operativo. Mantener flujo editorial natural, sin bloques de navegación.';
}

function inferWritingFromReference(value) {
  const txt = plainText(value);
  const lower = txt.toLowerCase();
  const technicalSignals = /(\bapi\b|\bsdk\b|\bjson\b|\bendpoint\b|\balgorit|\bquery\b|\bprisma\b|\bnode\b|\breact\b|\bsql\b|\bhttp\b)/i.test(lower) || /[{}();`]/.test(value);
  const opinionSignals = /(\bcreo\b|\bpienso\b|\bmi experiencia\b|\bdesde mi\b|\bopino\b|\bconsidero\b)/i.test(lower);
  const formalSignals = /(\basimismo\b|\bpor consiguiente\b|\ben consecuencia\b|\bcabe destacar\b|\ben este sentido\b)/i.test(lower);

  if (technicalSignals) {
    return {
      tipo: 'Técnico',
      estilo: 'Tomar como referencia la escritura custom: precisión técnica, términos concretos y foco práctico.'
    };
  }

  if (opinionSignals) {
    return {
      tipo: 'Opinión',
      estilo: 'Tomar como referencia la escritura custom: voz argumentativa, criterio editorial y postura razonada.'
    };
  }

  if (formalSignals) {
    return {
      tipo: 'Formal',
      estilo: 'Tomar como referencia la escritura custom: tono formal, claro y estructurado.'
    };
  }

  return {
    tipo: 'Simple',
    estilo: 'Tomar como referencia la escritura custom: lenguaje claro, directo y natural.'
  };
}

