    topic:   ['cómo ', 'como ', 'how to ', 'paso a paso', 'step by step', 'configurar ', 'instalar ', 'desplegar ', 'deploy ', 'construir ', 'build ', 'migrar a ', 'migrate to', 'setup ', 'crear desde', 'create from'],
