const PRIORITY = ['howto', 'faq', 'review', 'listicle', 'devBlog', 'editorial', 'caseStudy', 'shortArticle'];

function scoreTemplate(key) {
  let score = 0;
  const reasons = [];
  for (const sig of SIGNALS[key].topic) {
    if (combined.includes(sig)) {
      score += 2;
      reasons.push('T:"' + sig.trim() + '"(+2)');
    }
  }
  for (const sig of SIGNALS[key].briefing) {
    if (combined.includes(sig)) {
      score += 2;
      reasons.push('B:"' + sig.trim() + '"(+2)');
    }
  }
  return { score, reasons };
}

const hasNumberedSteps = /\n\s*\d+[.)]\s+\S/.test(briefing) || /\bpaso\s+\d/i.test(combined) || /\bstep\s+\d/i.test(combined);
const questionCount = (combined.match(/\?/g) || []).length;
const hasCodeSignals  = /```[\s\S]*```/.test(briefing) || /\bfunction\s+\w+\s*\(/.test(briefing) || /\bconst\s+\w+\s*=/.test(briefing) || /\bimport\s+\{/.test(briefing);
const hasQuantData    = /\d+\s*%/.test(combined) || /\d+\s*ms\b/.test(combined) || /\d+\s*rps\b/i.test(combined) || /\bbenchmark\b/i.test(combined);
const hasConcreteOut  = /\b(instalar|configurar|desplegar|deploy|setup|crear|build)\b/i.test(topic);

const scores = {};
for (const key of PRIORITY) scores[key] = scoreTemplate(key);

if (hasNumberedSteps) { scores.howto.score += 5; scores.howto.reasons.push('STRUCT:steps(+5)'); }
if (questionCount >= 3) { scores.faq.score += 4; scores.faq.reasons.push('STRUCT:q' + questionCount + '(+4)'); }
if (hasCodeSignals)  { scores.devBlog.score += 4; scores.devBlog.reasons.push('STRUCT:code(+4)'); }
if (hasQuantData)    { scores.caseStudy.score += 4; scores.caseStudy.reasons.push('STRUCT:quant(+4)'); }

if (briefingLength > 800) {
  scores.caseStudy.score += 2; scores.editorial.score += 2;
  scores.caseStudy.reasons.push('LEN:long(+2)'); scores.editorial.reasons.push('LEN:long(+2)');
} else if (briefingLength < 200) {
  scores.faq.score += 2; scores.shortArticle.score += 2;
  scores.faq.reasons.push('LEN:short(+2)'); scores.shortArticle.reasons.push('LEN:short(+2)');
}

if (scores.howto.score > 0 && scores.devBlog.score > 0 && scores.howto.score === scores.devBlog.score) {
  if (hasConcreteOut) { scores.howto.score += 1; scores.howto.reasons.push('TIE:output(+1)'); }
  else                { scores.devBlog.score += 1; scores.devBlog.reasons.push('TIE:conceptual(+1)'); }
}
if (scores.review.score > 0 && hasQuantData && / vs /.test(combined)) {
  scores.caseStudy.score += 2; scores.caseStudy.reasons.push('TIE:vs+quant(+2)');
}
const genericBizSignals = /\b(ia |inteligencia artificial|automatizaci|marketing|estrategia|negocio|empresa|organización|digital|datos|eficiencia|productividad|experiencia del cliente|cx\b)/i.test(combined);
const maxStructScore = Math.max(scores.howto.score, scores.faq.score, scores.review.score, scores.listicle.score, scores.devBlog.score, scores.caseStudy.score);
if (genericBizSignals && maxStructScore <= 4) {
  scores.editorial.score += 1; scores.editorial.reasons.push('GENERIC:biz(+1)');
}

if (genericBizSignals && hasNumberedSteps && !hasConcreteOut) {
  scores.howto.score = Math.max(0, scores.howto.score - 4); scores.howto.reasons.push('BIZ:noOutput(-4)');
  scores.editorial.score += 3; scores.editorial.reasons.push('BIZ:noOutput(+3)');
}

for (const key of PRIORITY) {
  const jitter = Math.floor(Math.random() * 2);
  scores[key].score += jitter;
  if (jitter > 0) scores[key].reasons.push('JITTER(+' + jitter + ')');
}

let maxScore = 0;
for (const key of PRIORITY) {
  if (scores[key].score > maxScore) maxScore = scores[key].score;
}

const candidates = PRIORITY.filter(key => scores[key].score >= maxScore - 3 && scores[key].score > 0);

let winner = null;
if (candidates.length > 1) {
  winner = candidates[Math.floor(Math.random() * candidates.length)];
} else if (candidates.length === 1) {
  winner = candidates[0];
}

if (!winner || maxScore === 0) {
  if (briefingLength > 600) winner = 'editorial';
  else if (questionCount >= 2) winner = 'faq';
  else winner = 'shortArticle';
}

const forcedKeyMap = {
  'HowTo': 'howto', 'FAQ': 'faq', 'Review': 'review',
  'Listicle': 'listicle', 'CaseStudy': 'caseStudy',
  'DevBlog': 'devBlog', 'Editorial': 'editorial', 'ShortArticle': 'shortArticle'
};
const forcedKey = forcedKeyMap[templateForzadoNorm];
const baseTemplate = TEMPLATES[forcedKey || winner];

const useTemplateCustom = modoCustomRaw.length > 0;
const useTipoCustom = modoCustomRaw.length > 0;

const templateNameResolved = useTemplateCustom ? 'Plantilla custom (derivada de referencia)' : baseTemplate.name;
const templateLengthHintResolved = useTemplateCustom ? inferLengthHintFromReference(modoCustomRaw) : baseTemplate.lengthHint;
const templateStructureGuideResolved = useTemplateCustom ? inferTemplateGuideFromReference(modoCustomRaw) : baseTemplate.structureGuide;
const templateKeyResolved = useTemplateCustom ? 'customDerived' : (forcedKey || winner);

let tipoEscrituraResolved = tipoEscrituraNorm;
let estiloRedaccionResolved = estiloRedaccionNorm;
if (useTipoCustom) {
  const writing = inferWritingFromReference(modoCustomRaw);
  if (!tipoEscrituraResolved) tipoEscrituraResolved = writing.tipo;
  if (!estiloRedaccionResolved) estiloRedaccionResolved = writing.estilo;
}

return [{
  json: {
    ...input,
    templateId:             baseTemplate.id,
    templateKey:            templateKeyResolved,
    templateName:           templateNameResolved,
    templateLengthHint:     templateLengthHintResolved,
    templateStructureGuide: templateStructureGuideResolved,
    tipoEscritura:          tipoEscrituraResolved,
    estiloRedaccion:        estiloRedaccionResolved,
    _templateScore:         maxScore,
    _templateBreakdown:     Object.fromEntries(PRIORITY.map(k => [k, scores[k]])),
    _customTemplateApplied: useTemplateCustom,
    _customWritingApplied:  useTipoCustom
  }
}];

const item = items[0].json;

function extractField(raw, field) {
  const re = new RegExp('"' + field + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"');
  const m = raw.match(re);
  return m ? m[1] : '';
}

function extractArrayField(raw, field) {
  const re = new RegExp('"' + field + '"\\s*:\\s*\\[([^\\]]*)\\]');
  const m = raw.match(re);
  if (!m) return [];
  const vals = m[1].match(/"((?:[^"\\\\]|\\\\.)*)"/g);
  return vals ? vals.map(s => s.slice(1, -1)) : [];
}

function extractContent(raw) {
  const keyIdx = raw.indexOf('"content"');
  if (keyIdx === -1) return '';
  const colonIdx = raw.indexOf(':', keyIdx + 9);
  const openQ = raw.indexOf('"', colonIdx + 1);
  if (openQ === -1) return '';
  const lastBrace = raw.lastIndexOf('}');
  const closeQ = raw.lastIndexOf('"', lastBrace);
  if (closeQ <= openQ) return '';
  return raw.substring(openQ + 1, closeQ);
}

let parsed = {};
let raw = (item.text || item.output || '').toString()
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/[\u00ab\u00bb\u201c\u201d]/g, '"')
  .replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
  .trim();

const startBrace = raw.indexOf('{');
const endBrace = raw.lastIndexOf('}');
if (startBrace !== -1 && endBrace > startBrace) raw = raw.substring(startBrace, endBrace + 1);

try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = {
    title: extractField(raw, 'title'),
    slug: extractField(raw, 'slug'),
    excerpt: extractField(raw, 'excerpt'),
    focusKeyphrase: extractField(raw, 'focusKeyphrase') || extractField(raw, 'focus_keyphrase'),
    categoryNames: extractArrayField(raw, 'categoryNames').length ? extractArrayField(raw, 'categoryNames') : extractArrayField(raw, 'categories'),
    tags: extractArrayField(raw, 'tags'),
    content: extractContent(raw)
  };
  if (!parsed.title && !parsed.content) {
    throw new Error('No se pudo extraer titulo ni contenido del JSON malformado');
  }
}

let catsArray = parsed.categoryNames || parsed.categories || [];
if (Array.isArray(catsArray)) {
  catsArray = catsArray.map(c => c.toString().trim()).filter(Boolean);
} else {
  catsArray = catsArray.toString().replace(/[\[\]"']/g, '').split(',').map(c => c.trim()).filter(Boolean);
}

let tagsArray = parsed.tags || [];
if (Array.isArray(tagsArray)) {
  tagsArray = tagsArray
    .flatMap(tag => tag.toString().split(/[,;|]/g))
    .map(tag => tag.trim().toLowerCase())
    .filter(Boolean);
} else {
  tagsArray = tagsArray.toString().replace(/[\[\]"']/g, '').split(/[,;|]/g).map(tag => tag.trim().toLowerCase()).filter(Boolean);
}
tagsArray = [...new Set(tagsArray)].slice(0, 3);

function sanitizeHrefValue(value) {
  let sanitized = value
    .replace(/\\+/g, '')
    .replace(/&quot;|%22/gi, '"')
    .trim();

  const lastHttps = sanitized.lastIndexOf('https://');
  const lastHttp = sanitized.lastIndexOf('http://');
  const lastProtocolIndex = Math.max(lastHttps, lastHttp);

  if (lastProtocolIndex > 0) {
    sanitized = sanitized.slice(lastProtocolIndex);
  }

  sanitized = sanitized
    .replace(/^(?:"|')+/g, '')
    .replace(/(?:\/?(?:"|'))+$/g, '')
    .replace(/^\/+((?:https?:\/\/))/i, '$1')
    .replace(/\s+/g, '');

  return sanitized;
}

let rawContent = parsed.content || '';
if (typeof rawContent === 'string') {
  rawContent = rawContent.replace(/\\n/g, ' ').replace(/\\\\/g, '');
  rawContent = rawContent.replace(/href\s*=\s*(["'])(.*?)\1/gi, (match, quote, hrefValue) => {
    const sanitizedHref = sanitizeHrefValue(hrefValue);
    return sanitizedHref ? `href="${sanitizedHref}"` : match;
  });
  const firstTag = rawContent.indexOf('<');
  const lastTag = rawContent.lastIndexOf('>');
  if (firstTag !== -1 && lastTag > firstTag) {
    rawContent = rawContent.substring(firstTag, lastTag + 1);
  }
}

function clean(value) {
  if (!value) return '';
  return value.toString().replace(/[\u00ab\u00bb\\]/g, '').trim();
}

const rawLanguage = ($('Execute Workflow Trigger').first().json.language || '').toString().toLowerCase();
const targetLanguage = (rawLanguage.includes('ing') || rawLanguage.includes('english')) ? 'en' : 'es';
const contentText = rawContent.toString().replace(/<[^>]+>/g, ' ');
const textForLang = [
  clean(parsed.title),
  clean(parsed.excerpt),
  clean(parsed.focusKeyphrase || parsed.focus_keyphrase || ''),
  contentText
].join(' ').toLowerCase();

const esStops = ['el','la','los','las','un','una','unos','unas','y','o','pero','porque','que','de','del','al','en','para','por','con','sin','sobre','entre','como','es','son','ser','se','su','sus','lo','ya','no','si','hay','mas','menos','muy','tambien','esta','este','estos','estas'];
const enStops = ['the','and','or','but','because','that','of','to','in','for','by','with','without','on','between','as','is','are','be','it','its','this','these','those','not','if','there','more','less','very','also','from','into','than'];

function countStops(text, stops) {
  const tokens = text.match(/[a-z]+/g) || [];
  const stopSet = new Set(stops);
  let count = 0;
  for (const token of tokens) {
    if (stopSet.has(token)) count += 1;
  }
  return count;
}

const esCount = countStops(textForLang, esStops);
const enCount = countStops(textForLang, enStops);
const languageValid = targetLanguage === 'en'
  ? enCount >= 8 && enCount >= esCount * 1.35
  : esCount >= 8 && esCount >= enCount * 1.35;

const jsonLdData = parsed.json_ld || parsed.jsonLd || null;

return [{
  json: {
    ...$('Execute Workflow Trigger').first().json,
    title: clean(parsed.title),
    content: rawContent,
    text: rawContent,
    slug: clean(parsed.slug),
    excerpt: clean(parsed.excerpt),
    focusKeyphrase: clean(parsed.focusKeyphrase || parsed.focus_keyphrase || ''),
    status: 'publish',
    categoryNames: catsArray,
    tags: tagsArray,
    targetLanguage,
    languageValid,
    languageSource: item.languageSource || 'draft',
    languageScores: { esCount, enCount },
    json_ld: jsonLdData
  }
}];
